import{_ as i,l as n,o as e,c as l,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"支配与 φ","description":"","frontmatter":{"title":"支配与 φ","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dominator-phi.md","filePath":"cs/dominator-phi.md","lastUpdated":1789023840000}'),m={name:"cs/dominator-phi.md"};function c(_,a,u,S,A,D){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="支配与-φ" tabindex="-1">支配与 φ <a class="header-anchor" href="#支配与-φ" aria-label="Permalink to &quot;支配与 φ&quot;">​</a></h1><div class="epigraph"><p>$d$ 支配 $n$ 当每条从入口到 $n$ 的路都经过 $d$；支配边界是插入 φ 的位置，使汇合处每个名字仍只赋值一次。</p><footer>—— 据 Lengauer and Tarjan, A Fast Algorithm for Finding Dominators in a Flowgraph, 1979；Cytron et al., 1991 整理</footer></div><p>上一课<a href="/cs/ssa-form">SSA</a>已经声明：改名、φ 按支配边界放置，Cytron 高效，本课要直觉。SSA 课把 φ 当语义，支配一笔带过。本课不重写「一次赋值一名」。缺口是支配树与支配边界 \\(\\mathrm{DF}\\)：为何 φ 插在那里就不多不少。后课活跃变量在这张已改名的图上算区间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>入口 \\(s\\) 支配所有可达块。严格支配：排除自身。直接支配 \\(\\mathrm{idom}(n)\\) 是严格支配 \\(n\\) 的最「近」者，全体 \\(\\mathrm{idom}\\) 成树。支配边界：被 \\(n\\) 支配的块的后继里，那些<strong>不再</strong>被 \\(n\\) 严格支配的块——恰是「有的前驱带着 \\(n\\) 的定值、有的没有」的入口。对变量 \\(x\\) 的每个定值块，在 \\(\\mathrm{DF}\\) 插 \\(\\phi\\)，再迭代（φ 自己也是定值）。</p><p>缺口是这一定义，不是再解释 φ 要在后端拆掉。Lengauer–Tarjan 用 DFS 半支配在几乎线性时间算 \\(\\mathrm{idom}\\)；本课认算法名，不证。</p><h3 id="支配不是后支配" tabindex="-1">支配不是后支配 <a class="header-anchor" href="#支配不是后支配" aria-label="Permalink to &quot;支配不是后支配&quot;">​</a></h3><p>后支配是到出口的对偶，用于部分死代码、控制依赖。φ 放置用正向支配。不要把「必经出口」当 DF。</p><p><span class="marginnote">Lengauer–Tarjan 1979。Cytron et al. 1991 把 DF 与 SSA 连起来。Appel 1998 把 SSA 比作函数式。SSA 课已引二者；本课把树与边界写清，供数据流课默认「标量名已唯一」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算支配树（迭代交或 LT）。对每个变量的定值集求 DF 并插 φ。按支配序重命名栈：进入块 push 新名，离开 pop。φ 的第 \\(i\\) 个操作数来自第 \\(i\\) 个前驱的当前名。</p>',11)),(e(),s(h,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20ID%5B%22%E6%94%AF%E9%85%8D%E6%A0%91%22%5D%0A%20%20ID%20--%3E%20DF%5B%22%E6%94%AF%E9%85%8D%E8%BE%B9%E7%95%8C%22%5D%0A%20%20DF%20--%3E%20PHI%5B%22%E6%8F%92%20%CF%86%22%5D%0A%20%20PHI%20--%3E%20RNM%5B%22%E6%8C%89%E6%94%AF%E9%85%8D%E5%BA%8F%E6%94%B9%E5%90%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不可约 CFG 仍有支配树；DF 可能更肥，φ 更多，不要求先可约。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>剪枝 SSA：若定值从不在支配范围内被读，可不插。半剪枝用全局活跃，完整剪枝更贵。本课默认至少半剪枝直觉。φ 不是 ISA 指令：后课分配前在前驱末插 <code>move</code>。</p><p>与<a href="/cs/dfs-edge-types">DFS 边分类</a>：支配算法用 DFS 树；回边与支配关系相关但不是同一分类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算 <code>in/out</code> 活跃方程。不做 memory SSA。后课默认：标量已是 SSA，汇合点有 φ。数据流框架以活跃变量为代表下一课补——冲突图要的是同时活，不是支配。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>支配树给出 idom；DF 决定 φ 的位置。</li><li>改名沿支配序；φ 后端再拆。</li><li>活跃区间仍是下一课的对象。</li><li>出处：Lengauer and Tarjan, 1979；Cytron et al., 1991。</li></ul>',8))])}const E=i(m,[["render",c]]);export{F as __pageData,E as default};
